package com.dbu.reservation.infrastructure.repository;
import com.dbu.reservation.domain.model.*;import com.dbu.reservation.domain.repository.RoomRepository;import com.dbu.reservation.infrastructure.database.DatabaseConnection;import java.sql.*;import java.time.*;import java.util.*;
public final class JdbcRoomRepository implements RoomRepository {
 public List<Room> findAvailable(RoomType type,LocalDate date,LocalTime start,LocalTime end,int people){String q="SELECT rm.* FROM rooms rm WHERE rm.room_type=? AND rm.status='ACTIVE' AND rm.capacity>=? AND NOT EXISTS(SELECT 1 FROM reservations r WHERE r.room_id=rm.room_id AND r.reservation_date=? AND r.status='APPROVED' AND ?<r.end_time AND ?>r.start_time) ORDER BY rm.building,rm.room_name";List<Room> out=new ArrayList<>();try(Connection c=DatabaseConnection.open();PreparedStatement p=c.prepareStatement(q)){p.setString(1,type.name());p.setInt(2,people);p.setDate(3,java.sql.Date.valueOf(date));p.setTime(4,Time.valueOf(start));p.setTime(5,Time.valueOf(end));try(ResultSet r=p.executeQuery()){while(r.next())out.add(new Room(r.getLong("room_id"),r.getString("room_name"),RoomType.valueOf(r.getString("room_type")),r.getString("building"),r.getInt("floor"),r.getInt("capacity"),r.getString("equipment"),r.getString("status")));}return out;}catch(SQLException e){throw new IllegalStateException("Could not search rooms.",e);}}
}
